1795	    /// Decides whether to submit the given directory entry as a file to
1796	    /// search.
1797	    ///
1798	    /// If the entry is a path that should be ignored, then this is a no-op.
1799	    /// Otherwise, the entry is pushed on to the queue. (The actual execution
1800	    /// of the callback happens in `run_one`.)
1801	    ///
1802	    /// If an error occurs while reading the entry, then it is sent to the
1803	    /// caller's callback.
1804	    ///
1805	    /// `ig` is the `Ignore` matcher for the parent directory. `depth` should
1806	    /// be the depth of this entry. `result` should be the item yielded by
1807	    /// a directory iterator.
1808	    fn generate_work(
1809	        &mut self,
1810	        ig: &Ignore,
1811	        depth: usize,
1812	        root_device: Option<u64>,
1813	        fs_dent: fs::DirEntry,
1814	    ) -> WalkState {
1815	        let mut dent = match DirEntryRaw::from_entry(depth, &fs_dent) {
1816	            Ok(dent) => DirEntry::new_raw(dent, None),
1817	            Err(err) => {
1818	                return self.visitor.visit(Err(err));
1819	            }
1820	        };
1821	        let is_symlink = dent.file_type().map_or(false, |ft| ft.is_symlink());
1822	        if self.follow_links && is_symlink {
1823	            let path = dent.path().to_path_buf();
