1872	    /// Returns the next directory to descend into.
1873	    ///
1874	    /// If all work has been exhausted, then this returns None. The worker
1875	    /// should then subsequently quit.
1876	    fn get_work(&mut self) -> Option<Work> {
1877	        let mut value = self.recv();
1878	        loop {
1879	            // Simulate a priority channel: If quit_now flag is set, we can
1880	            // receive only quit messages.
1881	            if self.is_quit_now() {
1882	                value = Some(Message::Quit)
1883	            }
1884	            match value {
1885	                Some(Message::Work(work)) => {
1886	                    return Some(work);
1887	                }
1888	                Some(Message::Quit) => {
1889	                    // Repeat quit message to wake up sleeping threads, if
1890	                    // any. The domino effect will ensure that every thread
1891	                    // will quit.
1892	                    self.send_quit();
1893	                    return None;
1894	                }
1895	                None => {
1896	                    if self.deactivate_worker() == 0 {
1897	                        // If deactivate_worker() returns 0, every worker thread
1898	                        // is currently within the critical section between the
1899	                        // acquire in deactivate_worker() and the release in
1900	                        // activate_worker() below.  For this to happen, every
1901	                        // worker's local deque must be simultaneously empty,
1902	                        // meaning there is no more work left at all.
1903	                        self.send_quit();
1904	                        return None;
1905	                    }
1906	                    // Wait for next `Work` or `Quit` message.
1907	                    loop {
1908	                        if let Some(v) = self.recv() {
1909	                            self.activate_worker();
1910	                            value = Some(v);
1911	                            break;
1912	                        }
1913	                        // Our stack isn't blocking. Instead of burning the
1914	                        // CPU waiting, we let the thread sleep for a bit. In
1915	                        // general, this tends to only occur once the search is
1916	                        // approaching termination.
1917	                        let dur = std::time::Duration::from_millis(1);
1918	                        std::thread::sleep(dur);
1919	                    }
1920	                }
1921	            }
1922	        }
1923	    }
