1951	    fn deactivate_worker(&self) -> usize {
1952	        self.active_workers.fetch_sub(1, AtomicOrdering::Acquire) - 1
1953	    }
1954	
1955	    /// Reactivates a worker.
1956	    fn activate_worker(&self) {
