            let handles: Vec<_> = workers
                .into_iter()
                .map(|worker| {
                    let guard = QuitOnPanic(quit_now.clone());
                    s.spawn(move || {
                        // If anything in this worker panics (e.g., the
                        // caller's visitor or filter), then tell all other
                        // workers to quit. Otherwise, they could wait
                        // forever for this worker to become inactive.
                        let _guard = guard;
                        worker.run()
                    })
                })
