            // propagate the first one with its original payload.
            let mut panic = None;
            for handle in handles {
                if let Err(err) = handle.join() {
                    panic.get_or_insert(err);
                }
            }
            panic
        });
        if let Some(err) = panic {
            std::panic::resume_unwind(err);
        }
    }
