python3 - <<'EOF'
p='src/walk.rs'
s=open(p).read()
assert s.endswith("    }\n}\n")
tests='''
    /// Runs `f` on a separate thread and asserts that it panics within a
    /// reasonable amount of time (instead of, e.g., deadlocking). Returns the
    /// panic message.
    fn assert_panics_without_hang<F>(f: F) -> String
    where
        F: FnOnce() + Send + 'static,
    {
        let (tx, rx) = std::sync::mpsc::channel();
        std::thread::spawn(move || {
            let result = std::panic::catch_unwind(
                std::panic::AssertUnwindSafe(f),
            );
            let _ = tx.send(result);
        });
        let result = rx
            .recv_timeout(std::time::Duration::from_secs(30))
            .expect("parallel walk hung after a panic");
        let payload = result.expect_err("parallel walk did not panic");
        if let Some(msg) = payload.downcast_ref::<&str>() {
            msg.to_string()
        } else if let Some(msg) = payload.downcast_ref::<String>() {
            msg.clone()
        } else {
            panic!("unexpected panic payload")
        }
    }

    /// Creates a directory tree with enough directories to keep many
    /// threads busy.
    fn mk_panic_tree() -> TempDir {
        let td = tmpdir();
        for i in 0..20 {
            for j in 0..5 {
                mkdirp(td.path().join(format!("d{i}/e{j}")));
                wfile(td.path().join(format!("d{i}/e{j}/foo")), "");
            }
        }
        td
    }

    #[test]
    fn parallel_panic_in_visitor() {
        let td = Arc::new(mk_panic_tree());
        for _ in 0..20 {
            let td = td.clone();
            let msg = assert_panics_without_hang(move || {
                WalkBuilder::new(td.path())
                    .threads(40)
                    .build_parallel()
                    .run(|| Box::new(|_| panic!("oops!")));
            });
            assert_eq!(msg, "oops!");
        }
    }

    #[test]
    fn parallel_panic_in_visitor_late() {
        let td = Arc::new(mk_panic_tree());
        for _ in 0..20 {
            let td = td.clone();
            let msg = assert_panics_without_hang(move || {
                WalkBuilder::new(td.path())
                    .threads(8)
                    .build_parallel()
                    .run(|| {
                        Box::new(|result| {
                            let dent = result.unwrap();
                            if dent.path().ends_with("d7/e3/foo") {
                                panic!("found it");
                            }
                            WalkState::Continue
                        })
                    });
            });
            assert_eq!(msg, "found it");
        }
    }

    #[test]
    fn parallel_panic_in_visitor_trait() {
        use super::{ParallelVisitor, ParallelVisitorBuilder};

        struct Visitor;
        impl ParallelVisitor for Visitor {
            fn visit(
                &mut self,
                _: Result<DirEntry, crate::Error>,
            ) -> WalkState {
                panic!("visitor panic")
            }
        }
        struct Builder;
        impl<'s> ParallelVisitorBuilder<'s> for Builder {
            fn build(&mut self) -> Box<dyn ParallelVisitor + 's> {
                Box::new(Visitor)
            }
        }

        let td = Arc::new(mk_panic_tree());
        for _ in 0..20 {
            let td = td.clone();
            let msg = assert_panics_without_hang(move || {
                WalkBuilder::new(td.path())
                    .threads(40)
                    .build_parallel()
                    .visit(&mut Builder);
            });
            assert_eq!(msg, "visitor panic");
        }
    }

    #[test]
    fn parallel_panic_in_builder() {
        let td = Arc::new(mk_panic_tree());
        // Panic on various calls to the builder, including the first one
        // (used for the root paths) and ones while creating worker visitors.
        for panic_at in [0, 1, 2, 5, 10] {
            let td = td.clone();
            let msg = assert_panics_without_hang(move || {
                let mut count = 0;
                WalkBuilder::new(td.path())
                    .threads(10)
                    .build_parallel()
                    .run(|| {
                        if count == panic_at {
                            panic!("builder panic");
                        }
                        count += 1;
                        Box::new(|_| WalkState::Continue)
                    });
            });
            assert_eq!(msg, "builder panic");
        }
    }

    #[test]
    fn parallel_panic_in_filter() {
        let td = Arc::new(mk_panic_tree());
        for _ in 0..20 {
            let td = td.clone();
            let msg = assert_panics_without_hang(move || {
                WalkBuilder::new(td.path())
                    .threads(40)
                    .filter_entry(|dent| {
                        if dent.path().ends_with("e2") {
                            panic!("filter panic");
                        }
                        true
                    })
                    .build_parallel()
                    .run(|| Box::new(|_| WalkState::Continue));
            });
            assert_eq!(msg, "filter panic");
        }
    }
}
